# -*- coding: utf-8 -*-
"""
素材库 · 六年级上册（统编版）八个单元习作
================================================================
结构说明（想自己加题材，照这个格式抄就行）：

每个题材是一个 dict：
{
  "title": ["标题一", "标题二"],
  "paras": [
     [ slot, slot, slot ],      # 第1段（开头）
     [ slot, slot, slot, slot ],# 第2段（主体）
     ...
  ],
  "extra": [(25, "字数不够时补的句子。"), ...],
}

slot 是候选句列表，每句用 (最低适用分, "句子") 标注：
  25 = 最朴素的写法（流水账、形容词堆砌、口号式）
  27 = 有具体细节、一两处修辞
  29 = 有镜头感（动作/神态/心理）、对比藏在事里、结尾用画面

关键设计：同一个题材里的所有句子都在写同一件事，
所以怎么随机组合都不会前后矛盾（不会出现"拔河开头 + 义卖内容"）。

所有题材都来自真实生活：教室、操场、厨房、菜地、公交站、
爷爷奶奶的手、同桌的雨伞……不写空中楼阁。
"""

