                (27, "有一次他答完，老师笑着说：这就是我们班的智多星。"),
                (29, "那天下午教室里忽然响起一声特别长的嗝，全班哄堂大笑，连老师都笑了。"),
                (29, "从那以后大家给他起了个外号，叫龙咆哮。他一听就笑。"),
                (25, "他爱看科普书。"),
