# ============================================================
# 主线扩充第四批：u6 倡议书补 5 条（目标每单元 15 条）
# ------------------------------------------------------------
# 倡议书格式固定：称呼→现象→为什么→分条建议→号召→署名→日期。
# 每条只换主题和具体现象，但现象必须是学校里真能看见的。
# ============================================================
def _init(title, sub, intro, bad, why, tips, call, extra25, extra27):
    """按倡议书固定结构拼一条主线，省去重复样板。

    段落结构（每段 = [句槽, 句槽...]，每个句槽 = [(档, 句子), ...]）：
      称呼 / 引入 / 现象×2 / 原因×2 / 引导语 / 建议×4（各一段）/ 号召×2 / 署名 / 日期
    """
    def slot(pairs):
        return list(pairs)

    owner = [(25, "六（1）班 全体同学"), (27, "六（1）班 全体同学"), (29, "六（1）班 全体同学")]
    date = [(25, "2026年10月20日"), (27, "2026年10月20日"), (29, "2026年10月20日")]

    paras = [
        [[(25, "亲爱的同学们：")]],
        [slot(intro)],
        [slot(bad[0]), slot(bad[1])],
        [slot(why[0]), slot(why[1])],
        [slot([(25, "我提几条建议："), (27, "我在这里提几条建议：")])],
    ]
    paras += [[slot(t)] for t in tips]
    paras += [
        [slot(call[0]), slot(call[1])],
        [slot(owner)],
        [slot(date)],
    ]
    return {"title": [title, sub], "paras": paras,
            "extra": [(25, s) for s in extra25] + [(27, s) for s in extra27]}

