# 《关于保护环境的倡议书》原先把号召、署名、日期挤在同一段，
# 这里把三段拆开，并去掉重复 slot（否则 pick 时后两句会被 seen 判重而丢掉）
for _th in U6["themes"]:
    if _th["title"][0] != "关于保护环境的倡议书":
        continue
    _clean = []
    for _p in _th["paras"]:
        _slots = [sl for sl in _p
                  if not any(("六（1）班" in c[1] or "2026年" in c[1]) for c in sl)]
        if _slots:
            _clean.append(_slots)
    _clean.append([[(25, "六（1）班 全体同学"), (27, "六（1）班 全体同学"), (29, "六（1）班 全体同学")]])
    _clean.append([[(25, "2026年10月20日"), (27, "2026年10月20日"), (29, "2026年10月20日")]])
    _th["paras"] = _clean

# ============================================================
# 主线扩充第五批：u2 +2、u4 +3、u8 +3（8 条）
# ============================================================
def _line(title, sub, segs, extra25, extra27=()):
    """六段式主线：segs 是 [(段首句对, [slot对...]), ...]。"""
    paras = []
    for head, rest in segs:
        paras.append([list(head)] + [list(s) for s in rest])
    return {"title": [title, sub], "paras": paras,
            "extra": [(25, s) for s in extra25] + [(27, s) for s in extra27]}

