# _line() 返回的是完整的 {title, paras, extra}，而 variants 只接受段落列表。
# 这里统一拍平：dict 型变体取出 paras，extra 并入题材自己的 extra。
for _u in UNITS:
    for _th in _u["themes"]:
        _vs = _th.get("variants", [])
        if not _vs:
            continue
        _new = []
        for _v in _vs:
            if isinstance(_v, dict):
                _new.append(_v["paras"])
                _th.setdefault("extra", []).extend(_v.get("extra", []))
            else:
                _new.append(_v)
        _th["variants"] = _new


def _add2(themes, key, paras, extra25):
    """给指定题材追加一条变体：paras 直接是段落列表，不再经由中间函数。"""
    for th in themes:
        if th["title"][0] == key:
            th.setdefault("variants", []).append(paras)
            th.setdefault("extra", []).extend((25, s) for s in extra25)
            return True
    raise KeyError(key)

